#include "transition_background_projection.hpp"
#include "transition_orthogonal_background_jet.hpp"
using J=cubed_sphere::Jet;using Original=h::TransitionBackgroundJet;using Orth=h::TransitionOrthogonalBackgroundJet;
Real Scale(const Grid&g,size_t p){Real maxrow=0;for(int A=0;A<3;++A){Real sum=0;for(int a=0;a<3;++a)sum+=g.geometry[p].J[A][a]*g.geometry[p].J[A][a];maxrow=std::max(maxrow,std::sqrt(sum));}return 1/(g.n*maxrow);}
J SinJet(const J&a){J b(std::sin(a.f));for(int i=0;i<3;++i){b.d[i]=std::cos(a.f)*a.d[i];for(int j=0;j<3;++j)b.h[i][j]=std::cos(a.f)*a.h[i][j]-std::sin(a.f)*a.d[i]*a.d[j];}return b;}
J Delta(int mode,const Point&x){J y[3];for(int a=0;a<3;++a)y[a]=J::Variable(x[a],a);if(mode==0)return J(1);if(mode==1)return y[0]+J(.3)*y[1]-J(.7)*y[2]+y[0]*y[0]+J(.7)*y[0]*y[1]+J(2)*y[2]*y[2];if(mode==2||mode==3)return J(0);if(mode==4)return J(.001)*SinJet(J(3)*y[0])*SinJet(J(2)*y[1])+J(.001)*y[2]*y[2]*y[2];if(mode==5)return J(.001)*y[0]*y[1]/(y[0]*y[0]+y[1]*y[1]+y[2]*y[2]);if(mode==6)return J(.1)*SinJet(J(12)*y[0]+J(7)*y[1]-J(5)*y[2]);return J(.2)*cubed_sphere::Log(cubed_sphere::Power(y[0]*y[0]+y[1]*y[1]+y[2]*y[2],.5)+J(.17));}
Real Coefficient(int mode){return mode<2?0:(mode==3?.7:1);}
std::array<Real,24> PhysicalQuantities(U u,const Point&x){const auto omega=h::CompositeOmegaAt(x.data(),u);const auto c=h::EvolvedConstraints(u,omega);const auto p=h::ConformalRHS(u,omega,Real(4),Real(-.99),true);h::Z4cRHS<Real> rhs{};if(!c.valid||!h::AssembleInterior(p,omega.omega,rhs))throw std::runtime_error("invalid independent initial source");std::array<Real,24> out{};out[0]=c.hamiltonian;out[1]=std::sqrt(c.momentum_conformal_norm2);out[2]=rhs.chi;out[3]=rhs.trace;out[4]=rhs.theta;out[5]=h::WormholeLapseRate(x.data(),u);for(int t=0;t<6;++t){out[6+t]=rhs.metric[Engine::tensor_i[t]][Engine::tensor_j[t]];out[12+t]=rhs.a[Engine::tensor_i[t]][Engine::tensor_j[t]];}for(int i=0;i<3;++i){out[18+i]=rhs.lambda[i];out[21+i]=.005/.02*h::ReferenceTelegraphSupport(Radius(x.data()),.8,.24).value*u.alpha.d[i];}for(Real v:out)if(!std::isfinite(v))throw std::runtime_error("nonfinite full initial source");return out;}

J ModeJet(int mode,const Point&x){J y[3];for(int a=0;a<3;++a)y[a]=J::Variable(x[a],a);J r=cubed_sphere::Power(y[0]*y[0]+y[1]*y[1]+y[2]*y[2],.5);
 if(mode==0)return J(1);if(mode==1)return Delta(1,x);if(mode==2)return J(1.09)*cubed_sphere::Log(r);if(mode==3)return J(.5)*r;
 if(mode==4||mode==8){J t=J(12)*y[0]+J(7)*y[1]-J(5)*y[2],c(std::cos(t.f));for(int a=0;a<3;++a){c.d[a]=-std::sin(t.f)*t.d[a];for(int b=0;b<3;++b)c.h[a][b]=-std::sin(t.f)*t.h[a][b]-std::cos(t.f)*t.d[a]*t.d[b];}return J(.1)*c;}
 if(mode==5)return J(.01)*y[0]*y[0]/cubed_sphere::Power(r,1.5);if(mode==6)return J(.2)*cubed_sphere::Log(r+J(.17));return J(0);}
S ToS(const J&j){S q{};q.value=j.f;for(int a=0;a<3;++a){q.d[a]=j.d[a];for(int b=0;b<3;++b)q.dd[a][b]=j.h[a][b];}return q;}
S ScalarSample(Engine&engine,const V&state,const V&padded,size_t p,int field){const auto&g=engine.shift.grid;S q{};q.value=state[p*22+field];g.Derivatives(padded,field,p,q.d,q.dd);for(const auto&row:engine.supported_log_plans->Rows())if(row.active==p)return engine.supported_log_plans->Sample(row,state,22,field);return q;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=5)throw std::runtime_error("initial96 exact96 coefficient_functionals output.csv");auto grid=MakeGrid();auto initial=ReadInitial(argv[1],grid);const auto exact=ReadExact(argv[2]);std::array<V,2>w;for(auto&v:w)v.resize(initial.size());std::ifstream f(argv[3]);std::string magic;size_t count;f>>magic>>count;if(magic!="GLOBAL_BACKGROUND_FUNCTIONALS_V1"||count!=initial.size())throw std::runtime_error("coefficient layout");Real l1[2]{};for(size_t p=0;p<count;++p){size_t id;f>>id>>w[0][p]>>w[1][p];if(!f||id!=p)throw std::runtime_error("coefficient ordering");for(int field=0;field<2;++field){if(!std::isfinite(w[field][p]))throw std::runtime_error("coefficient finite");l1[field]+=std::abs(w[field][p]);}}
 Engine engine(grid.mesh,true,1e-10,4,true,true,0,6,true,2,.24,true,true,true,true,.24,1);engine.Initialize(0,false);engine.InitializeWormhole(argv[1],0,false);const V seed=engine.state,surface=engine.scri->values;const V basepadded=engine.Padded(seed);
 std::vector<size_t>queries{0,1,126,127,5319,39340,7816};std::array<std::vector<S>,2>base,truth;for(int field=0;field<2;++field)for(size_t p:queries){base[field].push_back(ScalarSample(engine,seed,basepadded,p,field?18:0));truth[field].push_back(StoredExact(grid.geometry[p].x,exact.at({0,p}),field));}
 std::ofstream csv(argv[4]);csv<<std::setprecision(17)<<"point,field,mode,coefficient,h,method,scaled_gradient_error,scaled_hessian_error,H_error,source_error_max,correction_gradient_noise_bound,correction_hessian_noise_bound\n";std::cout<<std::setprecision(17);
 for(int mode=0;mode<9;++mode){V state=seed;engine.scri->values=surface;Real coefficients[2]{};
  for(size_t p=0;p<count;++p){Point x{grid.geometry[p].x[0],grid.geometry[p].x[1],grid.geometry[p].x[2]};const auto delta=ModeJet(mode,x);for(int field=0;field<2;++field){const int v=field?18:0;state[22*p+v]=(mode>=7?seed[22*p+v]:0)+delta.f;coefficients[field]+=w[field][p]*state[22*p+v];}}
  for(size_t p=0;p<engine.scri->rows.size();++p){const auto&x=engine.scri->rows[p].geometry.x;const auto delta=ModeJet(mode,{x[0],x[1],x[2]});for(int v:{0,18})engine.scri->values[22*p+v]=(mode>=7?surface[22*p+v]:0)+delta.f;}
  const auto padded=engine.Padded(state);
  for(size_t qi=0;qi<queries.size();++qi){const size_t p=queries[qi];const auto&xx=grid.geometry[p].x;const Point x{xx[0],xx[1],xx[2]};const Real spacing=Scale(grid,p);const auto initial_jet=Analytic(x,exact.at({0,p}));for(int field=0;field<2;++field){S expected=ToS(ModeJet(mode,x));if(mode>=7){expected.value+=truth[field][qi].value;for(int a=0;a<3;++a){expected.d[a]+=truth[field][qi].d[a];for(int b=0;b<3;++b)expected.dd[a][b]+=truth[field][qi].dd[a][b];}}S physical{};if(Chart(x.data(),field).Reconstruct(expected,physical)!=h::PositiveFieldStatus::valid)throw std::runtime_error("exact mode positivity");auto target=initial_jet;if(field==0)target.chi=physical;else target.alpha=physical;const auto reference=PhysicalQuantities(target,x);const auto old=ScalarSample(engine,state,padded,p,field?18:0);S corrected=old;Real dg=0,dh=0;for(int a=0;a<3;++a){const Real delta=truth[field][qi].d[a]-base[field][qi].d[a];corrected.d[a]+=coefficients[field]*delta;dg=std::max(dg,spacing*std::abs(delta)*l1[field]);for(int b=0;b<3;++b){const Real d2=truth[field][qi].dd[a][b]-base[field][qi].dd[a][b];corrected.dd[a][b]+=coefficients[field]*d2;dh=std::max(dh,spacing*spacing*std::abs(d2)*l1[field]);}}
   for(int method=0;method<2;++method){const auto&q=method?corrected:old;Real eg=0,eh=0;for(int a=0;a<3;++a){eg=std::max(eg,spacing*std::abs(q.d[a]-expected.d[a]));for(int b=0;b<3;++b)eh=std::max(eh,spacing*spacing*std::abs(q.dd[a][b]-expected.dd[a][b]));}S actual{};if(Chart(x.data(),field).Reconstruct(q,actual)!=h::PositiveFieldStatus::valid)throw std::runtime_error("mode positivity");auto actual_jet=initial_jet;if(field==0)actual_jet.chi=actual;else actual_jet.alpha=actual;const auto measured=PhysicalQuantities(actual_jet,x);Real source=0;for(int channel=2;channel<24;++channel)source=std::max(source,std::abs(measured[channel]-reference[channel]));csv<<p<<','<<field<<','<<mode<<','<<coefficients[field]<<','<<spacing<<','<<(method?"global_free_background":"supported_base")<<','<<eg<<','<<eh<<','<<measured[0]-reference[0]<<','<<source<<','<<dg<<','<<dh<<'\n';}
  }}std::cout<<"{\"mode\":"<<mode<<",\"chi_coefficient\":"<<coefficients[0]<<",\"alpha_coefficient\":"<<coefficients[1]<<"}\n";
 }
 if(!csv)throw std::runtime_error("probe CSV write");std::cout<<"{\"phase\":\"summary\",\"queries\":7,\"modes\":9,\"all_active_coefficient_donors\":"<<count<<",\"current_full_linear_halo_and_supported58_operator\":true,\"production_adopted\":false,\"full_effective_derivative_weight_qualification\":false}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
